from __future__ import annotations; import re; from pathlib import Path; ROOT = Path(__file__).resolve().parents[2]; NEXT_CONFIG = ROOT / 'apps' / 'frontend' / 'next.config.mjs'; ANALYTICS = ROOT / 'apps' / 'frontend' / 'src' / 'components' / 'RootClients.tsx'
def _script_src_hosts() -> str: text = NEXT_CONFIG.read_text(encoding='utf-8'); m = re.search('"script-src ([^"]+)"', text); assert m, 'no script-src directive found in next.config.mjs CSP'; return m.group(1)
def _required_external_script_hosts() -> set[str]: hosts: set[str] = set(); m = re.search('DEFAULT_OPENPANEL_API_URL\\s*=\\s*"https://([^/"]+)', ANALYTICS.read_text(encoding='utf-8')); hosts.add(m.group(1)) if m else None; return hosts
def test_csp_script_src_allows_every_external_script_host() -> None:
    directive = _script_src_hosts(); required = _required_external_script_hosts(); assert required, 'expected to derive at least the OpenPanel script host from code'
    for host in required: allowed = f'https://{host}' in directive or f"https://*.{host.split('.', 1)[1]}" in directive; assert allowed, f'CSP script-src does not allow script host {host!r} that the frontend loads.\n  script-src: {directive}\n  Add https://{host} (or the wildcard parent) to next.config.mjs, or the browser will block the script.'
    'AC1.10.4'; 'AC1.10.4'; _m1_directive = _script_src_hosts(); _m1_has_unsafe_eval = "'unsafe-eval'" in _m1_directive; assert not _m1_has_unsafe_eval, f"Production baseline CSP script-src must not contain 'unsafe-eval': {_m1_directive!r}"
